function calendar(){let d=new Date();d.setDate(d.getDate()+calendarOffset*7);d.setDate(d.getDate()-((d.getDay()+6)%7));let days=Array.from({length:7},(_,i)=>{let x=new Date(d);x.setDate(d.getDate()+i);return day(x)});return card('Calendario ritiri e partenze',`<div class="toolbar">${btn('←','cal','-1')}<strong>${days[0]} — ${days[6]}</strong>${btn('Oggi','cal','0')}${btn('→','cal','1')}</div><div class="calendar">${days.map(x=>`<div class="day"><strong>${x.slice(8)}/${x.slice(5,7)}</strong><small>${D.orders.filter(o=>o.day===x&&active(o)).length} ritiri</small>${D.orders.filter(o=>(o.day===x||o.dispatch===x)&&o.status!=='Annullata').sort((a,b)=>a.time.localeCompare(b.time)).map(o=>btn((o.method==='pickup'?o.time:'Spedizione')+' '+(o.name||o.id),'order',o.id)).join('')}</div>`).join('')}</div>`)}
let productionDate='',reportPeriod='all';function production(){
 const dateKey=o=>o.day||o.dispatch||'';
 const os=D.orders.filter(o=>['Confermata','In preparazione','Pronta'].includes(o.status)&&(!productionDate||dateKey(o)===productionDate)).sort((a,b)=>(dateKey(a)||'9999').localeCompare(dateKey(b)||'9999')||a.time.localeCompare(b.time));
 const agg=new Map(),ingredients=new Map(),missing=[];
 for(const o of os)for(const l of o.lines){const a=agg.get(l.id)||{id:l.id,total:0,prepared:0};a.total+=l.qty;a.prepared+=prepared59(o,l);agg.set(l.id,a)}
 for(const a of agg.values()){const p=prod(a.id),remaining=Math.max(0,a.total-a.prepared);if(remaining<.0000001)continue;const r=recipe59(a.id);if(!r||r.sale_unit!==p?.unit||!r.ingredients.length){missing.push(p?.it||String(a.id));continue;}for(const i of r.ingredients){const key=i.name.trim().toLocaleLowerCase('it-IT')+'|'+i.unit;const x=ingredients.get(key)||{name:i.name,unit:i.unit,amount:0};x.amount+=Number(i.qty)*remaining;ingredients.set(key,x)}}
 const groups=[['Forno e pasticceria',['bakery','sweet']],['Carne e gastronomia',['meat','deli','cheese']]];
 return `<div class="ops-intro"><div><div class="eyebrow">LABORATORIO · PIANIFICAZIONE</div><h2>Produzione da organizzare</h2><p>Quantità ordinate, preparate e ancora da lavorare.</p></div>${btn('Ricettario','recipes59','','primary')}</div>${D.opsError?`<div class="banner">${esc(D.opsError)} Il piano resta consultabile; le quantità parziali non sono disponibili.</div>`:''}<div class="metrics">${metric('Ordini in programma',os.length)}${metric('Prodotti da completare',[...agg.values()].filter(x=>x.total-x.prepared>.000001).length)}${metric('Ricette mancanti',D.ops?missing.length:'—')}</div>`+card('Piano per laboratorio',`<div class="toolbar"><label>Data ritiro / partenza<input type="date" id="production-date" value="${esc(productionDate)}"></label>${btn('Tutte le date','production-all')}${btn('Stampa lista','print')}</div>`+groups.map(([label,cs])=>{const rows=[...agg.values()].filter(a=>cs.includes(prod(a.id)?.cat));return `<h3>${label}</h3>`+(rows.length?table(['Prodotto','Ordinato','Preparato','Da preparare','Avanzamento'],rows.map(a=>{const p=prod(a.id),unit=esc(p?.unit==='buc'?'pz':p?.unit||'');return [esc(p?.it||a.id),qty(a.total)+' '+unit,D.ops?qty(a.prepared)+' '+unit:'—',D.ops?qty(Math.max(0,a.total-a.prepared))+' '+unit:'—',D.ops?`<progress max="${a.total}" value="${a.prepared}"></progress> ${Math.round(a.prepared/a.total*100)}%`:'—']})):empty('Nessuna lavorazione'))}).join(''))+card('Ingredienti necessari · quantità ancora da preparare',!D.ops?empty('Attiva SQL 06 per calcolare gli ingredienti.'):((missing.length?`<p class="banner">Calcolo parziale: ricetta mancante o unità cambiata per ${esc(missing.join(', '))}.</p>`:'')+(ingredients.size?table(['Ingrediente','Fabbisogno','Unità'],[...ingredients.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(i=>[esc(i.name),qty(i.amount),esc(i.unit)])):empty('Nessun fabbisogno calcolabile.'))+'<small>Stima dalle ricette inserite. Non sottrae le materie prime disponibili e non modifica le scorte.</small>'))+card('Ordini per priorità',os.length?os.map(o=>`<article class="ops-order"><div class="ops-order-head"><div><strong>${esc(o.name||o.id)}</strong><br><small>${esc(dateKey(o)||'Da programmare')} ${esc(o.time)} · ${esc(o.status)}</small></div>${btn('Apri ordine','order',o.id)}</div>${table(['Prodotto','Preparato / ordinato',''],o.lines.map(l=>[esc(l.it),D.ops?qty(prepared59(o,l))+' / '+qty(l.qty)+' '+esc(l.unit):'—',D.ops&&o.status!=='Pronta'?btn('Aggiorna','prepare59',o.id+':'+l.id,'smallbutton'):'']))}</article>`).join(''):empty('Nessun ordine in preparazione'));
}
function prepared59(o,l){return o.status==='Pronta'?l.qty:Math.min(l.qty,Math.max(0,Number(D.ops?.progress?.find(x=>x.order_id===o.id&&Number(x.product_id)===l.id)?.prepared||0)));}
