 const metrics=`<div class="sr71-real-stats">${metric('Incassi netti',eur(all.reduce((s,o)=>s+net(o),0)))}${metric('Rimborsi registrati',eur(all.reduce((s,o)=>s+o.refund,0)))}${metric('Da incassare',eur(all.filter(active).reduce((s,o)=>s+Math.max(0,due(o)-net(o)),0)),'Ordini aperti')}</div>`;
 const list=os.length?os.map(o=>{const balance=Math.max(0,due(o)-net(o));const status=o.status==='Annullata'?pill('Annullato','none'):balance<=0?pill('Saldo ricevuto','good'):net(o)>0?pill('Acconto ricevuto','low'):pill('Da incassare','low');return `<article class="sr71-real-row"><div class="sr71-real-ident"><strong>${esc(o.name||'Cliente')}</strong><small>${esc(o.id)} · ${esc(date(o.created))}</small><span>${esc(sr71PaymentName(o.payment))} · ${status}</span></div><div class="sr71-real-money"><div><small>Dovuto</small><strong>${eur(due(o))}</strong></div><div><small>Incassato netto</small><strong>${eur(net(o))}</strong></div><div><small>Saldo</small><strong>${eur(balance)}</strong></div></div>${btn('Gestisci ordine','order',o.id,'smallbutton')}</article>`}).join(''):sr71Empty(all.length?'Nessun pagamento corrisponde alla ricerca.':'Non ci sono ancora ordini commerciali.','Gli ordini di prova sono visibili nella sezione Sandbox.');
