 const state=clients62,seq=++state.seq,session=user;state.offset=Math.max(0,offset);state.query=String(query).slice(0,150);state.loading=true;state.error='';if(page==='customers')render();
 try{await ensureSession();const data=await srRequest('/rest/v1/rpc/sr_customers62',{p_search:state.query,p_offset:state.offset},token);if(clients62!==state||state.seq!==seq||user!==session)return;state.data=data;}
 catch(e){if(clients62!==state||state.seq!==seq||user!==session)return;state.data=null;state.error=e.status===404?'Esegui SQL 09 in Supabase per attivare l’archivio degli account.':'Archivio non disponibile: '+e.message;}
 finally{if(clients62===state&&state.seq===seq&&user===session){state.loading=false;if(page==='customers')render();}}
