 const metrics=d?`<div class="metrics">${metric('Account registrati',Number(d.total))}${metric('Email confermate',Number(d.confirmed))}${metric('Senza ordini',Number(d.without_orders))}${metric('Iscritti newsletter',Number(d.newsletter))}</div>`:'';
