 if(d&&!s.loading&&!s.error){body+=`<div class="sr62-pagination"><span>${Number(d.matched)} risultati · pagina ${Math.floor(s.offset/50)+1}</span>${s.offset>0?btn('← Precedente','clients62-prev'):''}${s.offset+50<Number(d.matched)?btn('Successiva →','clients62-next'):''}</div>`;}
 return `<p class="muted">Account del negozio, anche senza acquisti. Gli account dello staff sono esclusi.</p>${metrics}`+card('Clienti registrati',tools+body)+card('Acquisti come ospite',`<p class="muted">${guests.length} contatti dagli ordini senza account associato. Non vengono uniti automaticamente agli account con la stessa email.</p>`+search('Cerca negli acquisti come ospite')+(guests.length?table(['Cliente','Contatti','Ordini','Incassi netti',''],guests.filter(x=>match(x.name+' '+x.email+' '+x.phone)).map(x=>[esc(x.name||'—'),esc(x.email)+'<br>'+esc(x.phone),x.orders.length,eur(x.total),btn('Scheda','customer59',x.key,'smallbutton')])):empty('Nessun acquisto come ospite')));
