function reports(){const now=today(),prefix=reportPeriod==='day'?now:reportPeriod==='month'?now.slice(0,7):reportPeriod==='year'?now.slice(0,4):'',matchPeriod=x=>!prefix||day(new Date(x)).startsWith(prefix);const os=D.orders.filter(o=>o.status!=='Annullata'&&matchPeriod(o.created)),ag={},cash=(D.paymentRows||[]).filter(p=>matchPeriod(p.created_at)),netCash=cash.reduce((a,p)=>a+(p.kind==='refund'?-1:1)*Number(p.amount),0),daily={};for(const p of cash){const d=day(new Date(p.created_at));daily[d]=(daily[d]||0)+(p.kind==='refund'?-1:1)*Number(p.amount)}for(const o of os)for(const l of o.lines){let a=ag[l.id]||={name:l.it,q:0,v:0,c:0};a.q+=l.qty;a.v+=l.qty*l.price;a.c+=l.qty*(prod(l.id)?.cost||0)}const max=Math.max(1,...Object.values(daily).map(Math.abs));return `<div class="card toolbar"><label>Periodo<select id="report-period">${[['all','Tutto'],['day','Oggi'],['month','Questo mese'],['year','Quest’anno']].map(([k,v])=>`<option value="${k}" ${reportPeriod===k?'selected':''}>${v}</option>`).join('')}</select></label>${btn('Stampa / PDF','print')}${btn('Esporta ordini CSV','export','orders')}</div><div class="metrics">${metric('Ordini',os.length)}${metric('Valore ordini',eur(os.reduce((s,o)=>s+due(o),0)))}${metric('Incassi netti registrati',eur(netCash))}${metric('Media ordine',eur(os.length?os.reduce((s,o)=>s+due(o),0)/os.length:0))}</div>`+card('Andamento incassi',Object.entries(daily).sort().slice(-45).map(([d,v])=>`<div class="sr42-bar"><span>${esc(d)}</span><div style="width:${Math.min(100,Math.abs(v)/max*100)}%;background:${v<0?'#ad654c':'#627852'}"></div><strong>${eur(v)}</strong></div>`).join('')||empty('Nessun movimento nel periodo'))+card('Prodotti ordinati per valore',table(['Prodotto','Quantità','Valore','Margine teorico*'],Object.values(ag).sort((a,b)=>b.v-a.v).map(a=>[esc(a.name),qty(a.q),eur(a.v),eur(a.v-a.c)]))+`<p class="muted">* Costo unitario attuale; non è utile fiscale, non include imposte, sconti, spedizione o spese. CSV completo, non limitato al periodo.</p>`);}
