function render(){if(!D)return;if(page==='settings'&&settingsDirty63&&$('settingsform'))return;if(!visible(page))page='dashboard';$('nav').innerHTML=menus.filter(x=>visible(x[0])).map(([id,icon,n])=>`<button class="${page===id?'active':''}" data-action="nav" data-id="${id}"><span>${icon}</span>${n}</button>`).join('');$('title').textContent=menus.find(x=>x[0]===page)[2];const unread=D.comms?.outbox?.filter(n=>n.channel==='in_app'&&!n.read).length||0;const nb=$('nav').querySelector('[data-id=notifications]');if(nb&&unread){const badge=document.createElement('b');badge.className='sr60-unread';badge.textContent=unread;nb.append(badge);}document.title=$('title').textContent+' | Sapori Rumeni Manager';const f={dashboard,orders:ordersPage,products:productRows,calendar,production,shipping:()=>ordersPage('shipping'),payments,customers,records,reports,notifications,settings:settingsPage,team,coupons:couponPage,reviews:reviewPage,audit:auditPage};$('content').innerHTML=f[page]();sr71Bind();if($('search'))$('search').oninput=e=>{filter=e.target.value;let pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos)};if($('sr62-client-search'))$('sr62-client-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();loadCustomers62(0,e.target.value)}};if($('production-date'))$('production-date').onchange=e=>{productionDate=e.target.value;render()};if($('report-period'))$('report-period').onchange=e=>{reportPeriod=e.target.value;render()};if($('statefilter'))$('statefilter').onchange=e=>{statusFilter=e.target.value;render()};if($('settingsform'))bindSettings63();if($('sr66-rotate'))$('sr66-rotate').onclick=async(e)=>{const button=e.currentTarget;if(button.disabled)return;if(!confirm('Rigenerare il link privato di prova? Il precedente non sarà più valido.'))return;button.disabled=true;try{await ensureSession();const newCode=await srRequest('/rest/v1/rpc/sr66_rotate',{},token);if(!/^[0-9a-f-]{36}$/i.test(newCode||''))throw Error('Nuovo link non disponibile');if(D?.stripe66){D.stripe66.invite=newCode;render();}await refresh();notice('Link rigenerato. Apri il nuovo negozio di prova: il carrello sarà vuoto.');}catch(e){notice(e.message,true);}finally{button.disabled=false;}}; }
function romeLocal(v){if(!v)return '';const p=Object.fromEntries(new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(v)).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day+'T'+p.hour+':'+p.minute}function romeUTC(v){if(!v)return '';let a=Date.parse(v+':00Z');if(!Number.isFinite(a))throw Error('Data non valida');let target=a;for(let i=0;i<3;i++)a+=target-Date.parse(romeLocal(new Date(a))+':00Z');if(romeLocal(new Date(a))!==v)throw Error('Orario non valido');return new Date(a).toISOString()}
function field(n,l,v='',type='text',attrs=''){return `<label>${esc(l)}<input name="${n}" type="${type}" value="${esc(v)}" ${attrs}></label>`}function area(n,l,v=''){return `<label class="full">${esc(l)}<textarea name="${n}">${esc(v)}</textarea></label>`}function select(n,l,v,opts){return `<label>${esc(l)}<select name="${n}">${opts.map(([k,t])=>`<option value="${esc(k)}" ${String(k)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
