const sr61CanClose=()=>!$('save').disabled||($('sr61-retry')&&!$('sr61-retry').hidden);$('close').onclick=$('cancel').onclick=()=>{if(sr61CanClose())$('modal').close()};$('modal').addEventListener('cancel',e=>{if(!sr61CanClose())e.preventDefault()});$('modalform').onsubmit=async e=>{e.preventDefault();if(!modalSave)return;let b=$('save');b.disabled=true;try{await modalSave(e.target,Object.fromEntries(new FormData(e.target)));$('modal').close();try{await refresh();notice('Modifica salvata')}catch(e){notice('Modifica salvata; aggiornamento dei dati non riuscito. Premi Aggiorna.',true)}}catch(err){notice(err.message,true);let el=$('modalbody').querySelector('.formerror');if(!el){el=document.createElement('p');el.className='formerror danger';$('modalbody').prepend(el)}el.textContent=err.message}finally{b.disabled=false}};
