 function updatePreview(){const src=gallery[0];preview.hidden=!src;placeholder.hidden=!!src;placeholder.textContent='Nessuna fotografia';if(src)preview.src=imagePath(src);else preview.removeAttribute('src');$('sr61-count').textContent=gallery.length+' / 6 fotografie';list.replaceChildren();gallery.forEach((src,i)=>{const card=document.createElement('div');card.className='sr61-photo';const img=document.createElement('img');img.src=imagePath(src);img.alt='Fotografia '+(i+1);const label=document.createElement('strong');label.textContent=i===0?'Principale':'Foto '+(i+1);card.append(img,label);const actions=document.createElement('div');actions.className='sr61-photo-actions';for(const [label,disabled,fn] of [['Principale',i===0,()=>{gallery.unshift(gallery.splice(i,1)[0]);}],['↑',i===0,()=>{[gallery[i-1],gallery[i]]=[gallery[i],gallery[i-1]];}],['↓',i===gallery.length-1,()=>{[gallery[i+1],gallery[i]]=[gallery[i],gallery[i+1]];}],['Rimuovi',gallery.length===1&&!!fallbackProductImages[p.id],()=>{gallery.splice(i,1);} ]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled||photoBusy||!galleryReady;b.setAttribute('aria-label',label==='↑'?'Sposta foto '+(i+1)+' prima':label==='↓'?'Sposta foto '+(i+1)+' dopo':label+' foto '+(i+1));b.onclick=()=>{if(photoBusy||gallerySaving)return;fn();updatePreview();status.textContent='Modifiche pronte. Premi Salva.';};actions.append(b);}card.append(actions);list.append(card);});for(const id of ['photo','camera','photo-use-url','photo-default','photo-undo']){const el=$(id);if(el)el.disabled=photoBusy||!galleryReady||(['photo','camera','photo-use-url','photo-default'].includes(id)&&gallery.length>=6)||(id==='photo-undo'&&JSON.stringify(gallery)===JSON.stringify(originalGallery));}save.disabled=photoBusy||!galleryReady||gallerySaving;}
