 async function choose(files){if(photoBusy||!galleryReady||gallerySaving)return;const incoming=Array.from(files||[]);if(!incoming.length)return;const slots=6-gallery.length;photoBusy=true;updatePreview();status.textContent='Preparazione delle foto…';const errors=[];let added=0;try{for(const file of incoming.slice(0,slots)){try{if(file.size>20*1024*1024)throw Error('Massimo 20 MB per foto');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usa JPG, PNG o WebP');const base64=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=()=>rej(Error('Impossibile leggere la foto'));r.readAsDataURL(file)});const result=await api('upload',{base64,mime:file.type});if(!activeEditor())return;if(!gallery.includes(result.image)){gallery.push(result.image);added++;}}catch(e){errors.push(file.name+': '+e.message);}}if(incoming.length>slots)errors.push('Massimo 6 foto: selezione limitata.');status.textContent=added+' foto aggiunte. Premi Salva. '+errors.join(' · ');}finally{if(activeEditor()){photoBusy=false;updatePreview();}}}
