function editOrder(id){delete $('modalform').dataset.lastOperation;delete $('modalform').dataset.operationId;let o=order(id);let opts=[o.status,...(trans[o.status]||[])].filter(s=>!(s==='Spedita'&&o.method==='pickup')&&!(s==='Pronta'&&o.method==='scheduled'));if(!manager()){opts=opts.filter(s=>s===o.status||['In preparazione','Pronta'].includes(s));modal(o.id,`<div class="stack">${table(['Prodotto','Quantità'],o.lines.map(l=>[esc(l.it),qty(l.qty)+' '+esc(l.unit)]))}${select('status','Stato',o.status,opts.map(x=>[x,x]))}</div>`,async(f,x)=>{if(x.status!==o.status)await api('order/prepare',{id,status:x.status})});return}
let canLines=active(o)&&o.status!=='Spedita'&&!o.paid&&!o.coupon;let closed=!active(o)||o.status==='Spedita';modal(o.id,`<div class="stack"><div><strong>${esc(o.name)}</strong><p>${esc(o.email)} · ${esc(o.phone)}</p><p>${esc(o.address||o.day+' '+o.time)}</p><small>Note cliente: ${esc(o.notes)}</small></div><div id="lines" class="stack">${o.lines.map(l=>lineHtml(l,canLines)).join('')}</div>${canLines?'<button type="button" id="addline">+ Prodotto</button>':''}<div class="fields">${select('status','Stato operativo',o.status,opts.map(x=>[x,x]))}${field('assignee','Assegna a',o.assignee)}${o.method==='pickup'&&!closed?field('day','Giorno ritiro',o.day,'date')+field('time','Ora ritiro',o.time,'time'):''}${!closed?field('fee','Spedizione €',o.fee,'number','min="0" step=".01"')+field('final','Totale definitivo €',o.final??'','number','min="0" step=".01"'):''}${field('tracking','Tracking',o.tracking)}${area('internal','Note interne',o.internal)}${field('paymentAmount','Registra incasso verificato €','','number','min=".01" step=".01"')}${owner()?field('refundAmount','Registra rimborso già eseguito €','','number','min=".01" step=".01"'):''}</div><div class="banner">${o.coupon?'Codice '+esc(o.coupon)+' · Sconto '+eur(o.discount)+' · ':''}Stima ${eur(o.total)} · Incasso netto ${eur(net(o))} · Saldo ${eur(Math.max(0,due(o)-net(o)))}. La registrazione non sposta denaro.</div><button type="button" id="printOrder">Stampa riepilogo</button>${o.method==='scheduled'?'<button type="button" id="printLabel">Stampa etichetta interna</button>':''}<div><h3>Storico</h3>${o.history.map(x=>`<small>${esc(date(x.time))} · ${esc(x.actor)} · ${esc(x.action)}</small><br>`).join('')}</div></div>`,async(f,x)=>{let p={id,status:x.status,internal:x.internal,tracking:x.tracking,assignee:x.assignee};if(x.day)p.day=x.day;if(x.time)p.time=x.time;if(x.fee!==undefined&&Number(x.fee)!==o.fee)p.fee=Number(x.fee);if(x.final!==undefined&&x.final!==''&&Number(x.final)!==o.final)p.final=Number(x.final);if(canLines){let lines=readLines();if(JSON.stringify(lines)!==JSON.stringify(o.lines.map(l=>({id:l.id,qty:l.qty,price:l.price}))))p.lines=lines}if(x.paymentAmount)p.paymentAmount=Number(x.paymentAmount);if(x.refundAmount)p.refundAmount=Number(x.refundAmount);if(f.elements.sendPayment?.checked){p.sendPayment=true;p.paymentLink=x.paymentLink}const fingerprint=JSON.stringify(p);if(f.dataset.lastOperation!==fingerprint){f.dataset.lastOperation=fingerprint;f.dataset.operationId=crypto.randomUUID();}p.operationId=f.dataset.operationId;await api('order/update',p)});if($('addline'))$('addline').onclick=()=>{$('lines').insertAdjacentHTML('beforeend',lineHtml({id:D.products[0].id,qty:1,price:D.products[0].price},true));wireLines()};wireLines();$('printOrder').onclick=()=>window.print();if($('printLabel'))$('printLabel').onclick=()=>{const w=window.open('','_blank','width=650,height=500');if(!w){notice('Consenti le finestre di stampa',true);return}w.opener=null;w.document.write('<!doctype html><html lang="it"><meta charset="utf-8"><title>Etichetta interna</title><style>body{font:18px system-ui;padding:30px}h1{font:28px Georgia}main{border:1px solid #222;padding:20px;width:100mm}small{font-size:11px}</style><main><h1>Sapori Rumeni</h1><p>Preparazione refrigerata</p><h2>'+esc(o.name)+'</h2><p>'+esc(o.address)+'</p><p>'+esc(o.phone)+'</p><p>'+esc(o.id)+'</p><small>Etichetta interna: non sostituisce la lettera di vettura del corriere.</small></main></html>');w.document.close();w.focus();w.print()}}
function lineHtml(l,editable){if(!editable)return `<div class="listrow"><span>${esc(l.it)}</span><strong>${qty(l.qty)} ${esc(l.unit)} · ${eur(l.price*l.qty)}</strong></div>`;return `<div class="orderline">${select('pid','Prodotto',l.id,D.products.filter(p=>p.active&&!p.archived||p.id===l.id).map(p=>[p.id,p.it]))}${field('lqty','Quantità',l.qty,'number','required min=".001" step=".001"')}${field('lprice','Prezzo unitario',l.price,'number','required min="0" step=".01"')}<button type="button" class="removeLine">×</button></div>`}
