/* Staff authentication: recovery never redirects to the customer site. */
let staffRecoveryToken=null,staffRecoveryEmail='',staffAuthBusy=false;
function staffFriendly(err){const x=String(err?.message||'').toLowerCase();if(x.includes('invalid login')||x.includes('invalid_credentials'))return 'Email o password non corrette. Controlla i dati oppure recupera la password.';if(x.includes('email not confirmed'))return 'Conferma prima il tuo indirizzo email.';if(x.includes('senza permessi'))return 'Questo account non è abilitato al Manager. Verifica i permessi staff su Supabase.';if(x.includes('rate limit')||x.includes('security purposes')||err?.status===429)return 'Troppe richieste. Attendi qualche minuto prima di riprovare.';if(x.includes('expired')||x.includes('invalid jwt')||err?.status===401)return 'Sessione o link non valido. Richiedi un nuovo link di recupero.';if(x.includes('fetch')||x.includes('abort')||x.includes('network'))return 'Connessione non disponibile. Riprova.';return err?.message||'Operazione non riuscita. Riprova.';}
function staffAuthMessage(text='',error=false){const n=$('loginerror');n.textContent=text;n.classList.toggle('auth-success',!error&&!!text);}
function staffAuthMode(mode){$('loginform').hidden=mode!=='login';$('staff-recover').hidden=mode!=='recover';$('staff-reset').hidden=mode!=='reset';$('recover-link').hidden=mode!=='login';$('back-login').hidden=mode==='login';$('auth-title').textContent=mode==='recover'?'Recupera la password.':mode==='reset'?'Scegli una nuova password.':'Il tuo negozio, in un unico posto.';$('auth-lead').textContent=mode==='recover'?'Inserisci l’indirizzo email del tuo account Manager.':mode==='reset'?'Imposta una nuova password per accedere al Manager.':'Accedi con il tuo account staff.';document.title=(mode==='recover'?'Recupera password':mode==='reset'?'Nuova password':'Accedi')+' | Sapori Rumeni Manager';staffAuthMessage();}
function staffRedirect(){if(location.protocol!=='https:')throw Error('Apri il Manager dal suo indirizzo HTTPS online per recuperare la password.');return new URL('index.html',location.href).href.split(/[?#]/)[0];}
async function staffAction(form,fn){if(staffAuthBusy)return;staffAuthBusy=true;const b=form.querySelector('[type=submit]'),old=b.innerHTML;b.disabled=true;b.textContent='Operazione in corso…';staffAuthMessage();try{await fn();}catch(e){staffAuthMessage(staffFriendly(e),true);}finally{b.innerHTML=old;b.disabled=false;staffAuthBusy=false;}}
function staffRevealReset(){document.querySelectorAll('[data-reveal]').forEach(b=>{const i=$(b.dataset.reveal);i.type='password';b.textContent='Mostra';b.setAttribute('aria-pressed','false');});}
function staffRoleCheck(id,t){return srRequest('/rest/v1/sr_staff?select=role,active&user_id=eq.'+encodeURIComponent(id),undefined,t).then(r=>{if(!r?.[0]?.active||!['owner','manager'].includes(r[0].role))throw Error('Account senza permessi Manager');return r[0];});}
function initStaffAuth(){
 document.querySelectorAll('[data-reveal]').forEach(b=>{b.onclick=()=>{const i=$(b.dataset.reveal);const show=i.type==='password';i.type=show?'text':'password';b.textContent=show?'Nascondi':'Mostra';b.setAttribute('aria-pressed',String(show));};});
 $('recover-link').onclick=()=>{staffAuthMode('recover');$('recover-email').value=$('loginform').elements.name.value;try{$('staff-redirect').textContent='Indirizzo di ritorno: '+staffRedirect();}catch(e){staffAuthMessage(e.message,true);}$('recover-email').focus();};
 $('back-login').onclick=()=>{if(staffAuthBusy)return;staffRecoveryToken=null;staffRecoveryEmail='';$('staff-reset').reset();staffRevealReset();staffAuthMode('login');};
 $('staff-recover').onsubmit=e=>{e.preventDefault();staffAction(e.currentTarget,async()=>{await srRequest('/auth/v1/recover?redirect_to='+encodeURIComponent(staffRedirect()),{email:$('recover-email').value.trim().toLowerCase()});staffAuthMessage('Se l’account esiste, riceverai un link di recupero. Controlla anche la posta indesiderata.');});};
 $('staff-reset').onsubmit=e=>{e.preventDefault();staffAction(e.currentTarget,async()=>{const pw=$('staff-new').value;if(!staffRecoveryToken)throw Error('Link non valido. Richiedi un nuovo link.');if(pw.length<8)throw Error('La password deve avere almeno 8 caratteri.');if(pw!==$('staff-confirm').value)throw Error('Le password non coincidono.');const r=await fetch(SR_SUPABASE.url+'/auth/v1/user',{method:'PUT',headers:{apikey:SR_SUPABASE.key,Authorization:'Bearer '+staffRecoveryToken,'Content-Type':'application/json'},body:JSON.stringify({password:pw}),cache:'no-store'});if(!r.ok){const j=await r.json().catch(()=>({}));const er=Error(j.message||j.msg||'Impossibile aggiornare la password.');er.status=r.status;throw er;}try{await srRequest('/auth/v1/logout?scope=local',{},staffRecoveryToken);}catch{}staffRecoveryToken=null;clearSession();$('staff-reset').reset();staffRevealReset();staffAuthMode('login');$('loginform').elements.name.value=staffRecoveryEmail;staffRecoveryEmail='';staffAuthMessage('Password aggiornata. Accedi con la nuova password.');});};
 $('staff-account').onclick=()=>{if(!user)return;$('staff-account-email').textContent=user.name;$('staff-account-role').textContent='Ruolo: '+(user.role==='owner'?'Titolare':'Manager');$('staff-account-dialog').showModal();};
 $('staff-account-close').onclick=()=>$('staff-account-dialog').close();
 $('staff-account-recover').onclick=async()=>{if(staffAuthBusy||!user)return;staffAuthBusy=true;const b=$('staff-account-recover');b.disabled=true;try{await srRequest('/auth/v1/recover?redirect_to='+encodeURIComponent(staffRedirect()),{email:user.name});$('staff-account-dialog').close();notice('Link di recupero richiesto. Controlla la tua email.');}catch(e){$('staff-account-dialog').close();notice(staffFriendly(e),true);}finally{staffAuthBusy=false;b.disabled=false;}};
 $('staff-logout-cancel').onclick=()=>$('staff-logout-dialog').close();$('staff-logout-confirm').onclick=async()=>{const b=$('staff-logout-confirm');b.disabled=true;try{await api('logout',{});}catch{}finally{if($('staff-logout-dialog').open)$('staff-logout-dialog').close();showLogin();$('loginform').reset();staffRevealReset();b.disabled=false;staffAuthMessage('Hai effettuato la disconnessione.');}};
 const hash=new URLSearchParams(location.hash.slice(1)),query=new URLSearchParams(location.search);
 const callback64=hash.has('access_token')||hash.has('error')||hash.has('error_code')||query.has('error')||query.has('error_code')||query.has('code');if(callback64){history.replaceState(null,'',location.pathname);removeStaff64(localStorage);removeStaff64(sessionStorage);clearSession();}
 if(hash.get('type')==='recovery'&&hash.get('access_token')){const t=hash.get('access_token');staffAuthMode('reset');const b=$('staff-reset').querySelector('[type=submit]');b.disabled=true;(async()=>{try{const u=await srRequest('/auth/v1/user',undefined,t);if(!u?.id)throw Error('Link non valido');await staffRoleCheck(u.id,t);staffRecoveryToken=t;staffRecoveryEmail=u.email||'';b.disabled=false;}catch(e){staffAuthMode('recover');staffAuthMessage(staffFriendly(e),true);}})();}
 else if(hash.has('error')||hash.has('error_code')||query.has('error')||query.has('error_code')||query.has('code')||hash.has('access_token')){staffAuthMode('recover');staffAuthMessage('Link non valido o scaduto. Richiedi un nuovo link dal Manager.',true);}
 else {staffAuthMode('login');document.addEventListener('DOMContentLoaded',()=>restoreStaff64().catch(e=>staffAuthMessage(staffFriendly(e),true)),{once:true});}
}

initStaffAuth();

/* V59: operations, shared across staff devices through dedicated RPCs. */
function requireOps59(){if(!D.ops)throw Error(D.opsError||'Esegui SQL 06 per attivare la funzione.');}
function recipesList59(){requireOps59();const rows=D.products.filter(p=>!p.archived);modal('Ricettario interno',`<p>Inserisci gli ingredienti necessari per 1 kg o 1 pezzo finito, secondo l’unità di vendita. I dati non sono pubblici.</p>${table(['Prodotto','Ricetta',''],rows.map(p=>{const r=recipe59(p.id);return [esc(p.it),r?.sale_unit===p.unit&&r.ingredients.length?pill(r.ingredients.length+' ingredienti','good'):pill('Da compilare','low'),btn('Modifica','recipe59',p.id,'smallbutton')]}))}`,null);}
function recipeEdit59(id){requireOps59();const p=prod(id);if(!p||p.archived)throw Error('Prodotto non disponibile');const r=recipe59(id);const old=r?.sale_unit===p.unit?r.ingredients:[];const row=i=>`<div class="recipe-line59">${field('ingredient','Ingrediente',i.name||'','text','maxlength="120" required')}${field('amount','Quantità',i.qty||'','number','min="0.000001" max="100000" step="0.000001" required')}${select('unit','Unità',i.unit||'kg',[['kg','kg'],['g','g'],['l','l'],['ml','ml'],['pz','pz']])}<button type="button" class="remove-recipe59" aria-label="Rimuovi ingrediente">×</button></div>`;modal('Ricetta · '+p.it,`<p>Quantità per <strong>1 ${p.unit==='buc'?'pezzo':'kg'} di prodotto finito</strong>, tenendo conto della resa reale.</p>${r&&r.sale_unit!==p.unit?'<p class="banner">Unità cambiata: ricompila la ricetta.</p>':''}<div id="recipe-lines59" class="stack">${(old.length?old:[{}]).map(row).join('')}</div><button id="recipe-add59" type="button">+ Ingrediente</button><small>Per azzerare la ricetta, rimuovi tutte le righe e salva.</small>`,async f=>{const ingredients=[...f.querySelectorAll('.recipe-line59')].map(n=>({name:n.querySelector('[name=ingredient]').value.trim(),qty:n.querySelector('[name=amount]').value,unit:n.querySelector('[name=unit]').value}));if(ingredients.some(i=>!i.name||!Number.isFinite(Number(i.qty))||Number(i.qty)<=0))throw Error('Controlla gli ingredienti');await api('recipe59',{id:p.id,unit:p.unit,updated_at:r?.updated_at||null,ingredients})});$('recipe-add59').onclick=()=>{if($('recipe-lines59').children.length<100)$('recipe-lines59').insertAdjacentHTML('beforeend',row({}));};$('recipe-lines59').onclick=e=>{const b=e.target.closest('.remove-recipe59');if(b)b.closest('.recipe-line59').remove()};}
function prepareEdit59(key){requireOps59();const [id,pid]=key.split(':'),o=order(id),l=o?.lines.find(x=>x.id===Number(pid));if(!o||!l||!['Confermata','In preparazione'].includes(o.status))throw Error('Ordine non modificabile');const previous=prepared59(o,l);modal('Aggiorna preparazione',`<p><strong>${esc(l.it)}</strong> · ${esc(o.name)}</p><p>Ordinato: ${qty(l.qty)} ${esc(l.unit)}. Inserisci il totale già preparato, non la quantità da aggiungere.</p><div class="fields">${field('prepared','Già preparato',previous,'number',`required min="0" max="${l.qty}" step="${l.unit==='buc'?'1':'.001'}"`)}</div><button type="button" id="all-prepared59">Segna tutto preparato</button><small>Non cambia lo stato dell’ordine e non scarica il magazzino.</small>`,async(f,x)=>api('prepare59',{order_id:id,product_id:l.id,ordered:l.qty,previous,prepared:Number(x.prepared)}));$('all-prepared59').onclick=()=>{$('modalform').elements.prepared.value=l.qty};}
function moveEdit59(id){requireOps59();const p=prod(id);if(!p||p.archived)throw Error('Prodotto non disponibile');const op=crypto.randomUUID();let fingerprint=null,operationId=op;modal('Movimento magazzino · '+p.it,`<div class="metrics">${metric('Fisico',qty(p.stock))}${metric('Riservato',qty(D.reserved[p.id]))}${metric('Vendibile',qty(available(p)))}</div><div class="fields">${select('direction','Tipo','in',[['in','Carico (+)'],['out','Scarico (−)']])}${field('quantity','Quantità '+(p.unit==='buc'?'pz':'kg'),'','number',`required min="${p.unit==='buc'?1:'.001'}" max="1000000" step="${p.unit==='buc'?1:'.001'}"`)}${field('reason','Causale (es. nuova produzione, scarto)','','text','required maxlength="250"')}</div><p id="move-preview59" class="banner" aria-live="polite"></p>`,async(f,x)=>{const q=Number(x.quantity),delta=x.direction==='out'?-q:q;if(!Number.isFinite(q)||q<=0||!x.reason.trim())throw Error('Inserisci quantità e causale');if(p.stock+delta<(D.reserved[p.id]||0)-.0000001)throw Error('Il movimento intacca le scorte riservate');const data={id:p.id,updated_at:p.updated_at,delta,reason:x.reason.trim()};const fp=JSON.stringify(data);if(fingerprint&&fingerprint!==fp)operationId=crypto.randomUUID();fingerprint=fp;await api('move59',{...data,operationId})});const f=$('modalform'),preview=()=>{const q=Number(f.elements.quantity.value||0),n=p.stock+(f.elements.direction.value==='out'?-q:q);$('move-preview59').textContent='Nuova giacenza: '+qty(n)+' '+(p.unit==='buc'?'pz':'kg')+(n<(D.reserved[p.id]||0)?' · inferiore alle prenotazioni!':'');};f.elements.quantity.oninput=preview;f.elements.direction.onchange=preview;preview();}
function stockHistory59(){const rows=D.audit.filter(a=>['stock_movement','stock_reason59'].includes(a.action)).map(a=>{try{return {...a,d:JSON.parse(a.detail)}}catch{return null}}).filter(Boolean);modal('Movimenti recenti',`<p>Movimenti con causale e modifiche automatiche, estratti dagli ultimi 200 eventi del registro. Un movimento manuale può apparire anche come variazione automatica.</p>${rows.length?table(['Data','Prodotto','Variazione','Prima / dopo','Causale'],rows.map(a=>[esc(date(a.time)),esc(prod(a.d.id)?.it||a.d.id),esc((Number(a.d.delta)>0?'+':'')+qty(a.d.delta)),qty(a.d.old)+' / '+qty(a.d.new),esc(a.d.reason||'Aggiornamento scorte')])):empty('Nessun movimento recente')}`,null);}

/* V60 communication and global search */
const mailEvents60={new_order:'Nuovo ordine',Confermata:'Confermato',Pronta:'Pronto',Spedita:'Spedito',Annullata:'Annullato',pickup_reminder60:'Promemoria ritiro', 'In preparazione':'In preparazione',Ritirata:'Ritirato',Consegnata:'Consegnato'};
function commsPanel60(){const c=D.comms;if(!c)return card('Comunicazioni',`<p>${esc(D.commsError||'Non disponibili')}</p>`);const labels={pending:'In coda',processing:'In lavorazione / da verificare',accepted:'Accettato dal provider',failed:'Errore',uncertain:'Esito incerto',skipped:'Saltato'};const inapp=c.outbox.filter(n=>n.channel==='in_app');const emails=c.outbox.filter(n=>n.channel==='email');return card('Notifiche interne',btn('Segna tutte come lette','read60','')+btn(browserEnabled60()?'Disattiva avvisi dispositivo':'Attiva avvisi dispositivo','browser60','')+'<p class="muted">Avvisi sul dispositivo mentre il Manager è aperto; le notifiche push a sito chiuso non sono ancora attive.</p>'+table(['Data','Evento','Lettura'],inapp.map(n=>[esc(date(n.created_at)),esc(mailEvents60[n.payload?.event]||n.payload?.event||''),pill(n.read?'Letta':'Nuova',n.read?'good':'low')])) )+card('Email automatiche',`<div class="banner">${c.mail.enabled?'Invio abilitato nel database. Verifica che il worker Brevo sia attivo.':'Invio sospeso. Configura e collauda il worker Brevo prima di attivarlo.'} Le email accettate dal provider non sono necessariamente consegnate. Le vecchie richieste non vengono inviate al momento dell’attivazione.</div>`+(owner()?btn(c.mail.enabled?'Sospendi invio':'Abilita invio','mail60','', 'primary'):'')+table(['Data','Evento','Destinatario','Esito','Dettagli'],emails.map(n=>[esc(date(n.created_at)),esc(mailEvents60[n.payload?.event]||n.payload?.event||''),esc(n.payload?.audience==='staff'?'Staff':'Cliente'),pill(!n.result&&n.status==='pending'&&(Date.parse(n.created_at)<Date.parse(c.mail.enabled_from)||Date.now()-Date.parse(n.created_at)>72*3600000)?'Storico · non inviato':labels[n.result||n.status]||n.status,n.result==='accepted'?'good':'low'),esc(n.error||'')])) )+card('Novità e newsletter',`<div class="metrics">${metric('Consensi newsletter validi',c.subscribers)}</div><p>Le novità pubblicate appaiono nel sito clienti. Le campagne email promozionali sono separate e richiedono ancora il collegamento Brevo Marketing e la sincronizzazione delle revoche.</p>`+(owner()?btn('+ Nuova notizia','news60','','primary'):'')+table(['Titolo italiano','Titolo rumeno','Visibilità',''],c.news.map(n=>[esc(n.title_it),esc(n.title_ro),pill(n.published?'Pubblicata':'Bozza',n.published?'good':'low'),owner()?btn('Modifica','news60',n.id,'smallbutton'):''])));}
async function commsMutate60(name,args){await ensureSession();await srRequest('/rest/v1/rpc/'+name,args,token);await refresh();notice('Salvato');}
function newsEdit60(id){const n=D.comms?.news.find(x=>x.id===id)||{};modal('Novità del negozio',`<div class="fields">${field('title_it','Titolo italiano',n.title_it||'','text','required maxlength="100"')}${field('title_ro','Titolo rumeno',n.title_ro||'','text','required maxlength="100"')}${area('body_it','Testo italiano',n.body_it||'')}${area('body_ro','Testo rumeno',n.body_ro||'')}<label class="line full"><input type="checkbox" name="published" ${n.published?'checked':''}> Pubblica sul sito clienti (non invia email)</label></div>`,async(f,x)=>{await ensureSession();await srRequest('/rest/v1/rpc/sr_news_save',{p:{...x,id:n.id||'',published:f.elements.published.checked}},token);});}
function globalSearch60(){modal('Ricerca rapida',`<label>Cerca prodotti, clienti o ordini<input id="sr60-global" type="search" autocomplete="off" placeholder="Nome, email, codice..."></label><div id="sr60-results" class="stack"></div>`,null);const input=$('sr60-global'),out=$('sr60-results');function run(){const q=input.value.trim().toLocaleLowerCase('it');if(q.length<2){out.textContent='Scrivi almeno due caratteri.';return;}const ps=D.products.filter(p=>[p.it,p.ro,p.barcode,p.supplier].join(' ').toLowerCase().includes(q)).slice(0,12),os=D.orders.filter(o=>[o.name,o.email,o.phone,o.id].join(' ').toLowerCase().includes(q)).slice(0,12);out.innerHTML='<h3>Prodotti</h3>'+ (ps.length?ps.map(p=>`<div class="sr60-result"><span>${esc(p.it)}</span>${btn('Apri','product',p.id,'smallbutton')}</div>`).join(''):'<p>Nessun risultato</p>')+'<h3>Ordini e clienti</h3>'+(os.length?os.map(o=>`<div class="sr60-result"><span>${esc(o.name)} · ${esc(o.status)}</span>${btn('Apri','order',o.id,'smallbutton')}</div>`).join(''):'<p>Nessun risultato</p>');}input.oninput=run;run();input.focus();}
function barcode60(){modal('Cerca codice a barre',`<p>Scansiona un codice con la fotocamera, oppure digitalo. La scansione dipende dal supporto del browser.</p><label>Codice<input id="sr60-code" autocomplete="off" inputmode="numeric"></label><button type="button" id="sr60-scan" class="smallbutton">Apri fotocamera</button><video id="sr60-camera" playsinline muted hidden style="width:100%;max-height:240px"></video><p id="sr60-scan-status" role="status"></p>`,null);const inp=$('sr60-code'),v=$('sr60-camera'),status=$('sr60-scan-status');let stream=null,timer=null;const stop=()=>{clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());stream=null;};$('modal').addEventListener('close',stop,{once:true});const find=()=>{const q=inp.value.trim();if(!q)return;stop();$('modal').close();nav('products');filter=q;render();};inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();find();}};const go=document.createElement('button');go.type='button';go.className='primary';go.textContent='Cerca prodotto';go.onclick=find;status.after(go);$('sr60-scan').onclick=async()=>{if(!window.BarcodeDetector||!navigator.mediaDevices?.getUserMedia){status.textContent='Scansione non supportata. Inserisci il codice manualmente.';return;}try{stop();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!v.isConnected||!$('modal').open){stop();return;}v.srcObject=stream;v.hidden=false;await v.play();const detector=new BarcodeDetector();let busy=false;timer=setInterval(async()=>{if(!v.isConnected||!$('modal').open){stop();return;}if(busy)return;busy=true;try{const rows=await detector.detect(v);if(rows[0]?.rawValue){inp.value=rows[0].rawValue;find();}}catch{status.textContent='Scansione non riuscita. Usa il codice manuale.';stop();}finally{busy=false;}},350);}catch{stop();status.textContent='Fotocamera non disponibile o permesso negato.';}};}

function browserEnabled60(){try{return localStorage.getItem('sr60_device_alerts')==='yes'&&window.Notification?.permission==='granted'}catch{return false}}
async function browserNotifications60(){if(browserEnabled60()){localStorage.removeItem('sr60_device_alerts');render();notice('Avvisi dispositivo disattivati.');return;}if(!window.Notification){notice('Notifiche non supportate dal browser.',true);return;}const permission=await Notification.requestPermission();if(permission!=='granted'){notice('Permesso non concesso.',true);return;}localStorage.setItem('sr60_device_alerts','yes');render();notice('Avvisi attivi mentre il Manager è aperto.');}
async function notifyOpen60(n){if(!browserEnabled60())return;try{const options={body:n+' nuovi ordini da verificare.',tag:'sr-new-orders',icon:'assets/icon-192.png'};const registration=await navigator.serviceWorker?.getRegistration();if(registration)await registration.showNotification('Sapori Rumeni Manager',options);else new Notification('Sapori Rumeni Manager',options);}catch{}}

/* V71 · payment workspace: commercial and sandbox views remain separate. */
function sr71PaymentName(v){return ({store:'Pagamento al ritiro',cash:'Contanti al ritiro',card:'Carta / Stripe',bank:'Bonifico bancario',transfer:'Bonifico bancario',bank_transfer:'Bonifico bancario',paypal:'PayPal'})[v]||String(v||'Non indicato');}
function sr71Empty(title,desc=''){return `<div class="sr67-empty sr71-empty"><span aria-hidden="true">◎</span><strong>${esc(title)}</strong>${desc?`<p>${esc(desc)}</p>`:''}</div>`;}
function sr71State(o){if(o.payment==='store')return o.status==='pending'?['Contanti · da incassare','low','cash']:o.status==='paid'?['Contanti · incassato (test)','good','cash']:['Contanti · '+(({expired:'Scaduto',failed:'Non riuscito'})[o.status]||'Da verificare'),'none','closed'];return ({paid:['Pagamento riuscito','good','paid'],pending:['In attesa','low','pending'],expired:['Scaduto / annullato','none','closed'],failed:['Non riuscito','none','closed']})[o.status]||['Da verificare','','closed'];}
function sr71Product(p){const catalog=prod(p.id);const raw=catalog?productImage(catalog):'';const src=/^(assets\/[a-zA-Z0-9_./-]+\.(?:webp|png|jpe?g)|https:\/\/[^\s<>"']+|data:image\/(?:webp|png|jpeg);base64,[a-z0-9+/=]+)$/i.test(raw)?raw:'';const q=Number(p.qty),pr=Number(p.price),total=p.lineTotal==null?Math.round(q*pr*100)/100:Number(p.lineTotal),unit=p.unit==='buc'?'pz':p.unit||'';return `<div class="sr71-product"><div class="sr71-photo" aria-hidden="true">${src?`<img src="${esc(src)}" alt="" loading="lazy"><span hidden>◇</span>`:'<span>◇</span>'}</div><div class="sr71-product-name"><strong>${esc(p.it||p.ro||'Prodotto')}</strong><small>${qty(q)} ${esc(unit)} · ${Number.isFinite(pr)?eur(pr)+' / '+esc(unit):'Prezzo non disponibile'}</small></div><strong class="sr71-product-price">${Number.isFinite(total)?eur(total):'—'}</strong></div>`;}
function sr71Order(o){const lines=Array.isArray(o.products)?o.products:[],state=sr71State(o),id=String(o.id||''),short=id.slice(0,8).toUpperCase();const key=esc(id);const extra=lines.length>3?`<div class="sr71-products sr71-extra">${lines.slice(3).map(sr71Product).join('')}</div>`:'';return `<article class="sr71-order"><div class="sr71-order-head"><div class="sr71-order-ident"><span class="sr71-order-code">TEST · ${esc(short)}</span><strong>${esc(o.name||'Cliente')}</strong><small>${o.registered?'Account registrato':'Ospite'} · ${esc(date(o.created_at))}</small></div><div class="sr71-order-total"><strong>${eur(o.total)}</strong>${pill(state[0],state[1])}<small>${o.payment==='store'?'Pagamento al ritiro':'Stripe · online'}</small></div></div><div class="sr71-products">${lines.slice(0,3).map(sr71Product).join('')||'<p class="muted">Nessun dettaglio prodotto disponibile.</p>'}</div><details class="sr71-detail" data-sr71-id="${key}" ${sr71Expanded.has(id)?'open':''}><summary><span>${lines.length>3?`Altri ${lines.length-3} prodotti e dettagli`:'Dettagli ordine'} <small>· ${lines.length} articoli diversi</small></span><span class="sr71-chevron" aria-hidden="true">⌄</span></summary>${extra}<div class="sr71-order-meta"><div><small>Codice completo</small><strong>${key}</strong></div><div><small>Ritiro simulato</small><strong>${esc(date(o.pickup_at))}</strong></div><div><small>Importo ordine</small><strong>${eur(o.total)}</strong></div><div><small>Incasso simulato online</small><strong>${eur(o.status==='paid'&&o.payment!=='store'?o.total:0)}</strong></div></div></details></article>`;}
function sr71Filtered(rows){const q=sr71Query.trim().toLocaleLowerCase('it');return rows.filter(o=>(!sr71Status||sr71State(o)[2]===sr71Status)&&(!q||[o.id,o.name,...(Array.isArray(o.products)?o.products.flatMap(p=>[p.it,p.ro]):[])].join(' ').toLocaleLowerCase('it').includes(q)));}
function sr71OrderList(rows,full=true){const filtered=full?sr71Filtered(rows):rows,limit=full?sr71Limit:5;return `<div class="sr71-list-heading"><h3>${full?'Storico ordini di prova':'Ultimi ordini di prova'}</h3><small>${Math.min(filtered.length,limit)} di ${filtered.length}</small></div>${filtered.length?`<div class="sr71-order-list">${filtered.slice(0,limit).map(sr71Order).join('')}</div>`:sr71Empty(rows.length?'Nessun risultato per i filtri selezionati.':'Nessun ordine di prova','Le transazioni simulate compariranno qui dopo il primo acquisto.')}${full&&filtered.length>limit?'<button type="button" id="sr71-more" class="sr71-more">Mostra altri ordini</button>':''}`;}
function sr71BindPhotos(root){root?.querySelectorAll('.sr71-photo img').forEach(img=>{const fail=()=>{img.hidden=true;if(img.nextElementSibling)img.nextElementSibling.hidden=false;};if(img.complete&&!img.naturalWidth)fail();else img.addEventListener('error',fail,{once:true});});}
function sr71Bind(){document.querySelectorAll('.sr71-compact .sr71-detail').forEach(n=>n.addEventListener('toggle',()=>{if(n.isConnected){if(n.open)sr71Expanded.add(n.dataset.sr71Id);else sr71Expanded.delete(n.dataset.sr71Id);}}));sr71BindPhotos($('content'));const area=$('sr71-test-list');if(!area)return;const update=()=>{area.innerHTML=sr71OrderList(D.stripe66?.rows||[]);bindList();};function bindList(){sr71BindPhotos(area);area.querySelectorAll('details[data-sr71-id]').forEach(n=>n.addEventListener('toggle',()=>{if(!n.isConnected)return;if(n.open)sr71Expanded.add(n.dataset.sr71Id);else sr71Expanded.delete(n.dataset.sr71Id);}));const more=$('sr71-more');if(more)more.onclick=()=>{sr71Limit+=10;update();};}bindList();const q=$('sr71-test-query'),status=$('sr71-test-status');if(q)q.oninput=()=>{sr71Query=q.value;sr71Limit=10;update();};if(status)status.onchange=()=>{sr71Status=status.value;sr71Limit=10;update();};}
function stripe66Panel(full=true){
 const a=D.stripe66;
 if(!a)return full?card('Stripe · Sandbox','<p class="muted">Area di prova non disponibile. Verifica SQL 11–14 e la connessione.</p>'):'';
 const rows=Array.isArray(a.rows)?a.rows:[];
 const link=a.invite&&/^[0-9a-f-]{36}$/i.test(a.invite)?'https://sapori-sito.netlify.app/?stripe_test='+encodeURIComponent(a.invite)+'#shop':'';
 const paid=rows.filter(o=>o.status==='paid'&&o.payment!=='store'),pending=rows.filter(o=>o.status==='pending'&&o.payment!=='store'),cash=rows.filter(o=>o.payment==='store'&&o.status==='pending');
 if(!full)return `<section class="card sr71-sandbox sr71-compact"><div class="sr71-section-title"><div><p class="eyebrow">SOLO SIMULAZIONI</p><h2>Ordini di prova</h2></div>${btn('Apri pagamenti','nav','payments','smallbutton')}</div><p class="muted">Non preparare o consegnare questi ordini.</p>${sr71OrderList(rows,false)}</section>`;
 const actions=link?`<div class="sr67-actions"><a class="sr67-launch" target="_blank" rel="noopener noreferrer" href="${esc(link)}">Apri negozio di prova <span aria-hidden="true">↗</span></a><button type="button" id="sr66-rotate">Rigenera link privato</button></div>`:'';
 return `<section class="card sr67-sandbox sr71-sandbox"><div class="sr67-head"><div><p class="eyebrow">AMBIENTE DI PROVA · SEPARATO DAGLI INCASSI</p><h2>Stripe Sandbox</h2><p class="muted">Collauda gli acquisti con account oppure come ospite.</p></div><span class="sr67-tag">TEST</span></div><div class="sr67-stats sr71-test-stats"><div><small>Ultime prove</small><strong>${rows.length}</strong></div><div><small>Stripe riusciti</small><strong>${paid.length}</strong></div><div><small>Stripe in attesa</small><strong>${pending.length}</strong></div><div><small>Contanti da incassare</small><strong>${cash.length}</strong></div><div><small>Totale Stripe simulato</small><strong>${eur(paid.reduce((sum,o)=>sum+Number(o.total||0),0))}</strong></div></div>${actions}<p class="sr67-note">Nessun addebito reale. Non preparare o consegnare questi ordini. Gli importi simulati non modificano magazzino o incassi commerciali.</p><div class="sr71-filter"><label>Cerca ordine, cliente o prodotto<input id="sr71-test-query" type="search" placeholder="Es. Cozonac" value="${esc(sr71Query)}"></label><label>Stato<select id="sr71-test-status">${[['','Tutti'],['paid','Stripe riusciti'],['pending','Stripe in attesa'],['cash','Contanti al ritiro'],['closed','Scaduti / non riusciti']].map(([v,n])=>`<option value="${v}" ${sr71Status===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div id="sr71-test-list">${sr71OrderList(rows)}</div></section>`;
}
